export var abs=Math.abs;export var from=String.fromCharCode;export var assign=Object.assign;export function hash(r,t){return 45^charat(r,0)?(((t<<2^charat(r,0))<<2^charat(r,1))<<2^charat(r,2))<<2^charat(r,3):0}export function trim(r){return r.trim()}export function match(r,t){return(r=t.exec(r))?r[0]:r}export function replace(r,t,n){return r.replace(t,n)}export function indexof(r,t){return r.indexOf(t)}export function charat(r,t){return 0|r.charCodeAt(t)}export function substr(r,t,n){return r.slice(t,n)}export function strlen(r){return r.length}export function sizeof(r){return r.length}export function append(r,t){return t.push(r),r}export function combine(r,t){return r.map(t).join("")}export function filter(r,t){return r.filter(function(r){return!match(r,t)})}